const BASE_ID    = 'apprGGdynxDTZMZmO';
const WEBHOOK_ID = 'achhqSolaET3Br1hH';
const TABLE_ID   = 'tbl7Y9QHzO1TyWZDl';
const PAT        = '<AIRTABLE_PAT_REDACTED>';

const COL = {
  fldbhAtinaHacVbSb: 'ticket_id',
  fldsXKax4t2vZ6wNr: 'created_datetime',
  fldlcF1da85degGaW: 'agent',
  fldrKSwjCZ6r9LNfy: 'time_open',
  fldK5bHMFjVaoWimQ: 'resolved_datetime',
  fldlVplDGGSpSKpyh: 'status',
  fldxucQuRlzmvkeHK: 'location',
  fldzPZvAVIViYzXbs: 'within_sla',
  fldCpoWB4mfQBzHL1: 'sla',
  fldd5QeiehXSk0JjK: 'ticket_type',
  fldkvF88PU0fcR0uU: 'oos',
};

function flatten(v) {
  if (v == null) return null;
  if (typeof v !== 'object') return v;
  if (!Array.isArray(v) && v.name !== undefined) return v.name;
  if (v.valuesByLinkedRecordId) {
    const out = [];
    for (const id of v.linkedRecordIds || []) {
      for (const item of v.valuesByLinkedRecordId[id] || []) {
        if (item != null) out.push(typeof item === 'object' ? item.name : item);
      }
    }
    return out.join(', ') || null;
  }
  if (Array.isArray(v)) {
    return v.filter(x => x != null)
            .map(x => typeof x === 'object' ? x.name : x)
            .join(', ') || null;
  }
  return null;
}

const MONTHS = {jan:1,feb:2,mar:3,apr:4,may:5,jun:6,jul:7,aug:8,sep:9,oct:10,nov:11,dec:12};
const BKK_MIN = 420;   // Asia/Bangkok is UTC+7 year-round, no DST

function toIso(v) {
  if (typeof v !== 'string' || !v.trim()) return null;

  // ISO with an offset (webhook payloads) -> shift to Bangkok wall time
  if (/^\d{4}-\d{2}-\d{2}T/.test(v) && /(Z|[+-]\d{2}:?\d{2})$/.test(v)) {
    const d = new Date(v);
    if (isNaN(d)) return null;
    return new Date(d.getTime() + BKK_MIN * 60000).toISOString().slice(0, 19);
  }
  if (/^\d{4}-\d{2}-\d{2}/.test(v)) return v;   // ISO, no offset: already local

  const m = v.trim().match(
    /^(\d{1,2})[\/\-]([A-Za-z]{3,}|\d{1,2})[\/\-](\d{4})(?:[ ,]+(\d{1,2}):(\d{2}))?/
  );
  if (!m) return null;
  const [, d, mo, y, hh = '0', mi = '0'] = m;
  const mm = /^\d+$/.test(mo) ? +mo : MONTHS[mo.slice(0,3).toLowerCase()];
  if (!mm) return null;
  const p = n => String(n).padStart(2, '0');
  return `${y}-${p(mm)}-${p(d)}T${p(hh)}:${mi}:00`;
}

function coerce(col, v) {
  switch (col) {
    case 'created_datetime':
    case 'resolved_datetime':
      return toIso(v);
    case 'time_open':
      return v == null || v === '' ? null : Math.round(Number(v));
    case 'within_sla':
      return v === 'Yes' ? true : v === 'No' ? false : null;
    case 'oos':
      return v === true || v === 'checked' ? 'checked' : null;
    default:
      return v;
  }
}

let cursor = $input.first().json.cursor;
const rows = new Map();   // record_id → row, so later payloads overwrite earlier
const dead = new Set();

while (true) {
  const res = await this.helpers.httpRequest({
    url: `https://api.airtable.com/v0/bases/${BASE_ID}/webhooks/${WEBHOOK_ID}/payloads`,
    qs: { cursor },
    headers: { Authorization: `Bearer ${PAT}` },
  });
  for (const p of res.payloads) {
    const t = p.changedTablesById?.[TABLE_ID];
    if (!t) continue;
    for (const [rid, rec] of Object.entries({
      ...t.createdRecordsById,
      ...t.changedRecordsById,
    })) {
      const cells = {
        ...rec.unchanged?.cellValuesByFieldId,
        ...rec.current?.cellValuesByFieldId,
        ...rec.cellValuesByFieldId,
      };
      const row = { record_id: rid };
      for (const [fid, col] of Object.entries(COL)) {
        row[col] = coerce(col, flatten(cells[fid]));
      }
      rows.set(rid, row);
      dead.delete(rid);
    }
    for (const rid of t.destroyedRecordIds || []) {
      dead.add(rid);
      rows.delete(rid);
    }
  }
  cursor = res.cursor;
  if (!res.mightHaveMore) break;
}

const out = [
  ...[...rows.values()].map(r => ({ json: { op: 'upsert', ...r } })),
  ...[...dead].map(id => ({ json: { op: 'delete', record_id: id } })),
];
// always emit at least one item so the cursor node still runs
out.push({ json: { op: 'cursor', cursor } });
return out;
